-- READ ONLY. Run after approved apply, portrait drain, and next 04:23 UTC merge.
begin read only;
with batch(id,did) as(values ('fcc75b03-80c1-49cc-b675-eb6ac916d3b0'::uuid,'4304488'),('cc49be7c-cd9b-4eaa-88a2-06f3f202c6c4'::uuid,'8270419'),('9dbaa8ab-bef4-4690-9d1e-0f2e64f5a483'::uuid,'8722'),('d1ba9a33-dee7-41f0-85a6-f8e87bf7c8c7'::uuid,'1622339'),('d3739140-435f-43da-8bd1-24e92aff6c70'::uuid,'29966'),('8941dae6-4879-46d8-bf42-721166f7880a'::uuid,'20560'),('2c8e9ead-44b9-4482-b1a6-814480c33074'::uuid,'55738'),('46812b32-b9b5-48a9-9905-f79cd8b4cf44'::uuid,'866'),('3bc0ad49-5d5a-495f-8189-04425126743a'::uuid,'534'),('fd2407d9-32b9-4184-9476-c6f5f66a48ea'::uuid,'44126'),('464eeab3-e2ff-4dff-a7ec-6b499b6b88fe'::uuid,'270578'),('a2d05287-c666-46ef-8a60-57c750e1596d'::uuid,'48720'),('515ee18c-571b-403f-a371-d359c2c4c4a8'::uuid,'1029'),('16806488-f939-4cac-bc1f-56987318badf'::uuid,'41249'),('d362f060-be2a-4e38-9f6e-0202df4b90b3'::uuid,'3563778'),('1d2e7ab4-f4e1-4cc2-81ba-5ab92941d37c'::uuid,'59249'),('a750aa2f-956a-4dd4-ac68-0746c7f2e09f'::uuid,'36860'),('c5582c58-475c-4778-9af7-5c061fe4a87e'::uuid,'97988'),('f9250721-b691-4571-8ef5-4cdf3165bcd1'::uuid,'1300441'),('3d117c1a-850d-4577-b432-abae11642042'::uuid,'269'),('6ab1be02-3723-4082-89f3-fd82e9ec2a69'::uuid,'98545'))
select jsonb_build_object('checked_at',now(),
 'total_musicbrainz_discogs_links',(select count(*) from external_ids where provider='musicbrainz_discogs' and entity_type='artist'),
 'batch',(select jsonb_agg(jsonb_build_object('id',b.id,'artist_present',a.id is not null,'link_present',x.id is not null,'portrait_state',w.portrait_state,'portrait_matches',w.portrait_discogs_id::text=b.did,'picture',w.original_url is not null,'conflicting_direct_id',exists(select 1 from external_ids e where e.entity_id=b.id and e.entity_type='artist' and e.provider='discogs' and e.external_id<>b.did),'held_elsewhere',exists(select 1 from external_ids e where e.entity_id<>b.id and e.entity_type='artist' and e.provider in ('discogs','musicbrainz_discogs') and e.external_id=b.did))) from batch b left join artists a on a.id=b.id left join external_ids x on x.entity_id=b.id and x.entity_type='artist' and x.provider='musicbrainz_discogs' and x.external_id=b.did left join artwork w on w.entity_id=b.id and w.entity_type='artist'),
 'merge_run_after_batch',(select jsonb_agg(z) from(select j.jobname,d.start_time,d.end_time,d.status,d.return_message from cron.job_run_details d join cron.job j using(jobid) where j.jobname='indigo-merge-split-artists' and d.start_time>(select max(x.created_at) from external_ids x join batch b on b.id=x.entity_id where x.provider='musicbrainz_discogs' and x.entity_type='artist') order by d.start_time desc limit 1)z),
 'database_bytes',pg_database_size(current_database())
) as report;commit;
